def main():
    for stem,replacements in [('manuscript',MAIN),('supplement',SUPPLEMENT)]:
        path=PAPER/(stem+'.tex');source=path.read_text(encoding='utf-8')
        for before,after in replacements.items():source=source.replace(before,after)
        if stem=='manuscript':
            result=json.loads((ROOT/'results/reporting_sensitivity.json').read_text())['vibrio_comparison']
            forest,mean=result['forest'],result['mean']
            val=100*(1-forest['validation_mae']/mean['validation_mae'])
            test=100*(1-forest['test_mae']/mean['test_mae'])
            before='Laboratory10 Forest16 improves validation MAE from 0.6015 to 0.5719 and test MAE from 0.9329 to 0.8016.'
            after=f'Laboratory10 Forest16 reduces validation MAE from 0.6015 to 0.5719 ({val:.1f}\\% reduction) and test MAE from 0.9329 to 0.8016 ({test:.1f}\\% reduction) on the common targets.'
            source=source.replace(before,after)
            source=source.replace('Its 4,952-byte estimated payload exceeds 4,096 bytes, so its exclusion is a memory-rule decision, not failure to improve validation.', 'Its 4,952-byte estimated payload places this predictive improvement 856 bytes above the historical allocation, making the effect of the selection policy explicit.')
            source=source.replace('The paired interval includes zero. Five pond labels favor Ridge in point MAE, whereas T1 favors persistence; comparing Ridge\'s point MAE with the marginal interval of persistence would not test this paired contrast.', 'Five pond labels favor Ridge in point MAE, whereas T1 favors persistence. This label-level heterogeneity, together with the paired interval spanning zero, motivates retaining the temporal baseline and the paired comparison when choosing the next model revision.')
        if stem=='manuscript' and r'\paragraph{Contributions.}' not in source:
            anchor=r'\subsection{Position relative to prediction and embedded studies}'
            contribution=(r'\paragraph{Contributions.} The study provides three connected results: '
                r'(i) a frozen cross-year pH benchmark that exposes changes in model ranking and quantifies paired whole-pond uncertainty; '
                r'(ii) an observation-specific microbial error--resource frontier with an exact validation-selection breakpoint and sampling-date influence checks; and '
                r'(iii) a primary-model export and physical replay on two microcontrollers, including diagnosis and correction of forest split-boundary discrepancies. '
                r'Together they turn model evaluation into a traceable design procedure linking observations, selection policy and implementation fidelity.'+'\n\n')
            source=source.replace(anchor,contribution+anchor,1)
        path.write_text(source,encoding='utf-8')
    print('Evidence-led contribution wording synchronized; metrics and scope retained')

if __name__=='__main__':main()
